// STM32F103 USB FS device controller, single-buffer PMA endpoint subset.
// USB host tokens are explicit API calls; bytes always come from ARM firmware.
const BASE=0x40005c00,PMA=0x40006000;
export class STMUSB {
 constructor(r){this.r=r;this.reset();}
 reset(){this.ep=new Uint16Array(8);this.pma=new Uint16Array(256);this.cntr=3;this.events=0;this.daddr=0;this.btable=0;this.packets=0;}
 clocked(){return this.r.board.cpu!=='cortex-m4f'&&!!(this.r.regs.get(0x4002101c)&(1<<23));}
 clock48(){const cr=this.r.regs.get(0x40021000)||0,c=this.r.regs.get(0x40021004)||0,hse=this.r.board.hse||8000000,source=c&(1<<16)?hse/(c&(1<<17)?2:1):4000000,mul=Math.min(16,((c>>>18)&15)+2),hz=source*mul/(c&(1<<22)?1:1.5);if(!(cr&(1<<24))||Math.abs(hz-48000000)>1)throw Error('USB FS için RCC üzerinden 48 MHz saat gerekli.');}
 active(){return this.clocked()&&!(this.cntr&3)&&!!(this.daddr&128);}
 shared(){if(this.r.regs.get(0x4002101c)&(1<<25))throw Error('STM32F103 USB ve CAN aynı 512 bayt SRAM’i paylaşır; birlikte çalıştırılamaz.');}
 istr(){for(let i=0;i<8;i++)if(this.ep[i]&0x8080)return this.events|0x8000|(this.ep[i]&0x8000?16:0)|i;return this.events;}
 irqExtra(){return this.clocked()&&(this.istr()&this.cntr&0xff00)?8:0;}
 index(ep){return this.ep.findIndex(v=>(v&15)===ep&&(v&0x3030));}
 table(i,o){const at=this.btable+i*8+o;this.bounds(at,2);return at>>>1;}
 address(value){return value===(this.daddr&127);}
 hostReset(){if(!this.clocked()||(this.cntr&3))return 'DISCONNECTED';this.shared();this.clock48();this.ep.fill(0);this.daddr=0;this.events=0x400;this.packets=0;return 'ACK';}
 hostOut(address,endpoint,data,setup=false){if(!(data instanceof Uint8Array)||data.length>64)throw Error('USB FS paket sınırı 64 bayt.');if(!this.active()||!this.address(address))return 'DISCONNECTED';this.shared();this.clock48();const i=this.index(endpoint);if(i<0)return 'NAK';const status=this.ep[i]>>>12&3;if(status===1&&!setup)return 'STALL';if(status!==3&&!(setup&&(this.ep[i]&0x600)===0x200))return 'NAK';if(setup&&data.length!==8)throw Error('USB SETUP 8 bayt olmalı.');const count=this.pma[this.table(i,6)],capacity=count&0x8000?(((count>>>10)&31)+1)*32:((count>>>10)&31)*2;if(data.length>capacity)throw Error('USB RX paketi PMA tampon kapasitesini aşıyor.');const at=this.pma[this.table(i,4)];this.bounds(at,data.length);for(let n=0;n<data.length;n+=2)this.pma[(at+n)>>>1]=data[n]|((data[n+1]||0)<<8);this.pma[this.table(i,6)]=(count&0xfc00)|data.length;this.ep[i]=(this.ep[i]&~0x3800)|0xa000|(setup?0x800:0);if(setup)this.ep[i]=(this.ep[i]&~0x4070)|0x20;else this.ep[i]^=0x4000;this.packets++;return 'ACK';}
 hostIn(address,endpoint){if(!this.active()||!this.address(address))return {status:'DISCONNECTED'};this.shared();this.clock48();const i=this.index(endpoint);if(i<0)return {status:'NAK'};const status=this.ep[i]>>>4&3;if(status===1)return {status:'STALL'};if(status!==3)return {status:'NAK'};const at=this.pma[this.table(i,0)],count=this.pma[this.table(i,2)]&1023;this.bounds(at,count);if(count>64)throw Error('USB TX tek paket en fazla 64 bayt.');const data=Uint8Array.from({length:count},(_,n)=>(this.pma[(at+n)>>>1]>>>((n&1)*8))&255);this.ep[i]=((this.ep[i]&~0x30)|0xa0)^0x40;this.packets++;return {status:'ACK',data};}
 bounds(at,n){if((at&1)||at+n>512)throw Error('USB PMA adresi 512 bayt sınırını aşıyor.');}
 read(a,n){if(a>=PMA&&a<PMA+1024){if(a%4||![2,4].includes(n))throw Error('USB PMA hizalı16/32bit erişim gerektirir.');return this.clocked()?this.pma[(a-PMA)/4]:0;}if(a<BASE||a>BASE+0x50)return undefined;if(this.r.board.cpu==='cortex-m4f')throw Error('F401/F411 USB OTG FS farklı register mimarisi kullanır; F103 USB PMA geçerli değil.');if(a%4||![2,4].includes(n))throw Error('USB register hizalı16/32bit olmalı.');if(!this.clocked())return 0;const o=a-BASE;if(o<32)return this.ep[o/4];if(o===0x40)return this.cntr;if(o===0x44)return this.istr();if(o===0x48)return 0;if(o===0x4c)return this.daddr;if(o===0x50)return this.btable;throw Error('USB register kapsam dışı.');}
 write(a,v,n){if(a>=PMA&&a<PMA+1024){if(a%4||![2,4].includes(n))throw Error('USB PMA hizalı16/32bit erişim gerektirir.');if(this.clocked()){this.shared();this.pma[(a-PMA)/4]=v&65535;}return true;}if(a<BASE||a>BASE+0x50)return false;if(this.r.board.cpu==='cortex-m4f')throw Error('F401/F411 USB OTG FS farklı register mimarisi kullanır; F103 USB PMA geçerli değil.');if(a%4||![2,4].includes(n))throw Error('USB register hizalı16/32bit olmalı.');if(!this.clocked())return true;this.shared();const o=a-BASE;v&=65535;if(o<32){const old=this.ep[o/4];this.ep[o/4]=(old&v&0x8080)|((old^v)&0x7070)|(v&0x070f)|((v&0x8000)?old&0x800:0);return true;}if(o===0x40){this.cntr=v;if(v&1){this.ep.fill(0);this.events=0;this.daddr=0;}return true;}if(o===0x44){this.events&=v;return true;}if(o===0x48)return true;if(o===0x4c){this.daddr=v&255;return true;}if(o===0x50){this.btable=v&0x1f8;return true;}throw Error('USB register yazımı kapsam dışı.');}
}
